    def do_GET(self): self.handle_any("GET")
    def do_HEAD(self): self.handle_any("HEAD")
    def do_POST(self): self.handle_any("POST")
    def handle_any(self, verb):
        r = {
            "verb": verb,
            "path": self.path,
            "headers": {k.lower(): v for k, v in self.headers.items()},
        }
        LOG.append(r)
        sys.stderr.write("REQ " + json.dumps(r) + "\n"); sys.stderr.flush()
        # routing
        p = urllib.parse.urlparse(self.path).path
        code, body, ctype = self.route(p, verb)
        data = body.encode() if verb != "HEAD" else b""
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body.encode())))
        self.send_header("Server", "TestServer/1.0")
        self.end_headers()
        if verb != "HEAD":
            try: self.wfile.write(data)
            except Exception: pass

    def route(self, p, verb):
        # explicit config file
        try:
            cfg = json.load(open("/tmp/test/config.json"))
        except Exception:
            cfg = {}
        exact = cfg.get("exact", {})
        if p in exact:
            return exact[p][0], exact[p][1], "text/html"
        base = p.rstrip("/")
        if base in exact and p != base:
            # directory without trailing slash
            e = exact[base]
            if e[2] == "dir":
                return e[0], "", "text/html"
        if p.endswith("/"):
            d = base if base else "/"
            if d in cfg.get("listable", {}):
                body = "<html><head><title>Index of %s</title></head><body>\n" % p
                for name in cfg["listable"][d]:
                    if name.endswith("/"):
                        body += "<a href=\"%s\">%s</a><br>\n" % (name, name)
                    else:
                        body += "<a href=\"%s\">%s</a><br>\n" % (name, name)
                body += "</body></html>\n"
                return 200, body, "text/html"
        return 404, "Not Found", "text/html"

    def do_PUT(self): self.handle_any("PUT")

class TS(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True

port = int(sys.argv[1]) if len(sys.argv) > 1 else 8080
TS(("127.0.0.1", port), H).serve_forever()
