                if d.get("listable"):
                    body = "<html><head><title>Index of %s</title></head><body>\n" % p
                    for name in d.get("names", []):
                        if name.endswith("/"):
                            body += '<a href="%s">%s</a>/\n' % (name.rstrip('/'), name.rstrip('/'))
                        else:
                            body += '<a href="%s">%s</a>\n' % (name, name)
                    body += "</body></html>\n"
                    return 200, body, "text/html"
                return 200, "<html><head></head><body></body></html>\n", "text/html"
