                if d.get("noslash301", True):
                    return 301, "", "text/html"
                return 200, "<html><body>DIR</body></html>\n", "text/html"
        if p in files:
            return files[p][0], files[p][1], "text/html"
        return c.get("notfound", 404), "Not Found", "text/html"

class TS(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True

