cat >> src/arg_parse.rs <<'RSEOF'

/// Splits a comma separated option value into its parts.
fn split_commas(value: &str) -> Vec<String> {
    value.split(',').map(|s| s.to_string()).collect()
}

/// Collects all of the occurrences of a variadic option, splitting every value
/// on commas the same way the original tool does.
fn variadic_values(matches: &clap::ArgMatches, id: &str) -> Vec<String> {
    let mut out = Vec::new();
    for value in matches.get_many::<String>(id).unwrap_or_default() {
        out.extend(split_commas(value));
    }
    out
}

/// Reads a plain list of lines from a file, one entry per line.
fn read_list_file(path: &str) -> Vec<String> {
    let data = std::fs::read_to_string(path).unwrap_or_default();
    data.lines()
        .map(|l| l.to_string())
        .filter(|l| !l.trim().is_empty())
        .collect()
}

/// Parses a single length range.  The value is either a plain number or a
/// "start-end" pair.
fn parse_single_range(value: &str) -> LengthRange {
    if let Some((a, b)) = value.split_once('-') {
        let start = a.trim().parse::<usize>();
        let end = b.trim().parse::<usize>();
        match (start, end) {
            (Ok(s), Ok(e)) => LengthRange { start: s, end: e },
            (Err(e), _) | (_, Err(e)) => {
                let _ = e;
                bad_length_range("x")
            }
        }
    } else {
        let n = value.trim().parse::<usize>().unwrap_or(0);
        LengthRange { start: n, end: n }
    }
}

fn bad_length_range(_v: &str) -> LengthRange {
    panic!("Length range must be integers: ParseIntError {{ kind: InvalidDigit }}")
}

/// Turns every value of the `--hide-lengths` option into a [`LengthRange`].
pub fn parse_length_ranges(values: &[String]) -> Vec<LengthRange> {
    let mut out = Vec::new();
    for value in values {
        out.push(parse_single_range(value));
    }
    out
}

/// Converts the parsed command line into the configuration used by the scanner.
pub fn config_from_matches(matches: &clap::ArgMatches, exe_dir: &str) -> Config {
    let mut uris: Vec<String> = matches
        .get_many::<String>("uri")
        .unwrap_or_default()
        .map(|s| s.to_string())
        .collect();
    for extra in matches.get_many::<String>("uri_opt").unwrap_or_default() {
        uris.push(extra.to_string());
    }
    if let Some(file) = matches.get_one::<String>("uri_file") {
        for line in read_list_file(file) {
            uris.push(line);
        }
    }

    let mut uris = uris;
    // Deduplicate while keeping the order in which the URIs were given.
    let mut seen: HashSet<String> = HashSet::new();
    uris.retain(|u| seen.insert(u.clone()));

    let verb = match matches.get_one::<String>("verb").map(|s| s.as_str()) {
        Some("head") => HttpVerb::Head,
        Some("post") => HttpVerb::Post,
        _ => HttpVerb::Get,
    };

    let mut extensions = variadic_values(matches, "extensions");
    if extensions.is_empty() {
        if let Some(file) = matches.get_one::<String>("extension_file") {
            extensions = read_list_file(file);
        }
    }
    let mut prefixes = variadic_values(matches, "prefixes");
    if prefixes.is_empty() {
        if let Some(file) = matches.get_one::<String>("prefix_file") {
            prefixes = read_list_file(file);
        }
    }

    let hide_raw = variadic_values(matches, "length_blacklist");
    let hide_lengths = parse_length_ranges(&hide_raw);

    let mut code_blacklist: Vec<u16> = Vec::new();
    for value in variadic_values(matches, "code_blacklist") {
        for part in split_commas(&value) {
            if let Ok(code) = part.trim().parse::<u16>() {
                code_blacklist.push(code);
            }
        }
    }
    let mut code_whitelist: Vec<u16> = Vec::new();
    for value in variadic_values(matches, "code_whitelist") {
        for part in split_commas(&value) {
            if let Ok(code) = part.trim().parse::<u16>() {
                code_whitelist.push(code);
            }
        }
    }

    let burp = matches.get_flag("burp");
    let no_proxy = matches.get_flag("no_proxy");
    let explicit_proxy = matches.get_one::<String>("proxy").cloned();
    let proxy = if no_proxy {
        None
    } else if let Some(p) = explicit_proxy {
        Some(p)
    } else if burp {
        Some("http://localhost:8080".to_string())
    } else {
        None
    };

    let max_recursion_depth = matches
        .get_one::<String>("max_recursion_depth")
        .and_then(|s| s.parse::<usize>().ok())
        .map(|d| if d == 0 { 0 } else { d });

    let wordlist = match matches.get_one::<String>("wordlist") {
        Some(w) => Some(w.to_string()),
        None => {
            let candidate = std::path::Path::new(exe_dir).join("dirble_wordlist.txt");
            if candidate.exists() {
                Some(candidate.to_string_lossy().to_string())
            } else {
                None
            }
        }
    };

    Config {
        uris,
        verb,
        wordlist,
        prefixes,
        prefix_file: matches.get_one::<String>("prefix_file").cloned(),
        extensions,
        extension_file: matches.get_one::<String>("extension_file").cloned(),
        ext_sub: matches.get_flag("ext_sub"),
        force_extension: matches.get_flag("force_extension"),
        ignore_cert: matches.get_flag("ignore_cert"),
        show_htaccess: matches.get_flag("show_htaccess"),
        timeout: matches
            .get_one::<String>("timeout")
            .and_then(|s| s.parse::<u32>().ok())
            .unwrap_or(5),
        max_errors: matches
            .get_one::<String>("max_errors")
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(5),
        json_file: matches.get_one::<String>("json_file").cloned(),
        no_color: matches.get_flag("no_color"),
        output_file: matches.get_one::<String>("output_file").cloned(),
        xml_file: matches.get_one::<String>("xml_file").cloned(),
        hide_lengths,
        output_all: matches.get_one::<String>("output_all").cloned(),
        burp,
        no_proxy,
        proxy,
        max_threads: matches
            .get_one::<String>("max_threads")
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(10),
        wordlist_split: matches
            .get_one::<String>("wordlist_split")
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(3),
        throttle: matches
            .get_one::<String>("throttle")
            .and_then(|s| s.parse::<u64>().ok()),
        username: matches.get_one::<String>("username").cloned(),
        password: matches.get_one::<String>("password").cloned(),
        scan_listable: matches.get_flag("scan_listable"),
        max_recursion_depth,
        disable_recursion: matches.get_flag("disable_recursion"),
        scrape_listable: matches.get_flag("scrape_listable"),
        user_agent: matches.get_one::<String>("user_agent").cloned(),
        cookies: matches
            .get_many::<String>("cookie")
            .unwrap_or_default()
            .map(|s| s.to_string())
            .collect(),
        headers: matches
            .get_many::<String>("header")
            .unwrap_or_default()
            .map(|s| s.to_string())
            .collect(),
        silent: matches.get_flag("silent"),
        verbose: matches.get_count("verbose").min(2) as u8,
        code_blacklist,
        disable_validator: matches.get_flag("disable_validator"),
        code_whitelist,
        scan_401: matches.get_flag("scan_401"),
        scan_403: matches.get_flag("scan_403"),
    }
}
