//! HTTP request layer.
//!
//! Requests are performed with libcurl which is bound through a small set of
//! `extern "C"` declarations.  Only the handful of options that the scanner
//! needs are used which keeps the binding self contained and easy to audit.

#![allow(non_camel_case_types)]

use log::trace;

use crate::arg_parse::{Config, HttpVerb};

pub const CURL_ERROR_SIZE: usize = 256;

pub type CURL = *mut std::ffi::c_void;
pub type curl_off_t = i64;

#[repr(i32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CurlError {
    Ok = 0,
    UnsupportedProtocol = 1,
    FailedInit = 2,
    UrlMalformat = 3,
    NotBuiltIn = 4,
    CouldntResolveProxy = 5,
    CouldntResolveHost = 6,
    CouldntConnect = 7,
    WeirdServerReply = 8,
    RemoteAccessDenied = 9,
    FtpAcceptFailed = 10,
    FtpWeirdPassReply = 11,
    FtpAcceptFailed2 = 12,
    FtpWeirdPasvReply = 13,
    FtpWeird227Format = 14,
    FtpCantGetHost = 15,
    FtpCantSetType = 16,
    PartialFile = 18,
    RetrieveGotNothing = 19,
    QuoteError = 21,
    HttpReturnedError = 22,
    WriteError = 23,
    UploadFailed = 25,
    ReadError = 26,
    OutOfMemory = 27,
    OperationTimedout = 28,
    FtpCouldntSetType = 29,
    FtpPortFailed = 30,
    FtpCouldntUseRest = 31,
    FtpCouldntGetSize = 32,
    RangeError = 33,
    HttpPostError = 34,
    SslConnectError = 35,
    BadDownloadResume = 36,
    FileCouldntReadFile = 37,
    UseSSLFailed = 64,
    SendFailedRewind = 65,
    CurlFunction = 77,
    PeerFailedVerification = 60,
    GotNothing = 52,
    Unknown = 999,
}

pub const CURLOPT_WRITEDATA: i32 = 1;
pub const CURLOPT_URL: i32 = 2;
pub const CURLOPT_PROXY: i32 = 4;
pub const CURLOPT_USERPWD: i32 = 5;
pub const CURLOPT_PROXYUSERPWD: i32 = 6;
pub const CURLOPT_WRITEFUNCTION: i32 = 11;
pub const CURLOPT_ERRORBUFFER: i32 = 10;
pub const CURLOPT_POSTFIELDS: i32 = 15;
pub const CURLOPT_USERAGENT: i32 = 18;
pub const CURLOPT_HTTPHEADER: i32 = 23;
pub const CURLOPT_HEADERDATA: i32 = 29;
pub const CURLOPT_CUSTOMREQUEST: i32 = 36;
pub const CURLOPT_NOBODY: i32 = 44;
pub const CURLOPT_POST: i32 = 47;
pub const CURLOPT_FOLLOWLOCATION: i32 = 52;
pub const CURLOPT_SSL_VERIFYPEER: i32 = 64;
pub const CURLOPT_SSL_VERIFYHOST: i32 = 81;
pub const CURLOPT_ACCEPT_ENCODING: i32 = 102;
pub const CURLOPT_TIMEOUT_MS: i32 = 155;

pub const CURLINFO_RESPONSE_CODE: i32 = 0x0020_0000 + 2;

extern "C" {
    fn curl_easy_init() -> CURL;
    fn curl_easy_cleanup(handle: CURL);
    fn curl_easy_setopt(handle: CURL, option: i32, value: ...) -> CurlError;
    fn curl_easy_perform(handle: CURL) -> CurlError;
    fn curl_easy_getinfo(handle: CURL, option: i32, ...) -> CurlError;
    fn curl_easy_strerror(error: CurlError) -> *const std::ffi::c_char;
    fn curl_slist_append(list: *mut CurlSlist, data: *const std::ffi::c_char) -> *mut CurlSlist;
    fn curl_slist_free_all(list: *mut CurlSlist);
}

pub struct CurlSlist {
    next: *mut CurlSlist,
    data: *mut std::ffi::c_char,
}

/// A single HTTP response.
#[derive(Clone, Debug)]
pub struct Response {
    pub url: String,
    pub code: u16,
    pub body: Vec<u8>,
    pub headers: Vec<String>,
    pub location: Option<String>,
    pub error: Option<CurlFailure>,
}

/// Describes a request that did not complete.
#[derive(Clone, Debug)]
pub struct CurlFailure {
    pub code: CurlError,
    pub message: String,
}

impl Response {
    /// The number of body bytes that were received.
    pub fn size(&self) -> usize {
        self.body.len()
    }

    /// The value of the `Location` header if the response carries one.
    pub fn location(&self) -> Option<&str> {
        self.location.as_deref()
    }
}

/// Everything that stays the same for every request of a scan.
#[derive(Clone, Debug)]
pub struct RequestDefaults {
    pub verb: HttpVerb,
    pub timeout_ms: u64,
    pub ignore_cert: bool,
    pub user_agent: Option<String>,
    pub headers: Vec<String>,
    pub cookies: Vec<String>,
    pub proxy: Option<String>,
    pub username: Option<String>,
    pub password: Option<String>,
    pub proxy_credentials: Option<String>,
}

impl RequestDefaults {
    pub fn from_config(config: &Config) -> RequestDefaults {
        RequestDefaults {
            verb: config.verb,
            timeout_ms: u64::from(config.timeout) * 1000,
            ignore_cert: config.ignore_cert,
            user_agent: config.user_agent.clone(),
            headers: config.headers.clone(),
            cookies: config.cookies.clone(),
            proxy: config.proxy.clone(),
            username: config.username.clone(),
            password: config.password.clone(),
            proxy_credentials: None,
        }
    }
}

extern "C" fn write_callback(ptr: *mut u8, size: usize, nmemb: usize, out: *mut std::ffi::c_void) -> usize {
    let total = size * nmemb;
    unsafe {
        let sink = &mut *(out as *mut Vec<u8>);
        let slice = std::slice::from_raw_parts(ptr, total);
        sink.extend_from_slice(slice);
    }
    total
}

extern "C" fn header_callback(ptr: *mut u8, size: usize, nmemb: usize, out: *mut std::ffi::c_void) -> usize {
    let total = size * nmemb;
    unsafe {
        let sink = &mut *(out as *mut Vec<String>);
        let slice = std::slice::from_raw_parts(ptr, total);
        if let Ok(text) = std::str::from_utf8(slice) {
            sink.push(text.trim_end_matches(['\r', '\n']).to_string());
        }
    }
    total
}

unsafe fn set_opt_str(handle: CURL, option: i32, value: &str) {
    let c = std::ffi::CString::new(value).unwrap_or_default();
    curl_easy_setopt(handle, option, c.as_ptr());
}

unsafe fn set_opt_long(handle: CURL, option: i32, value: i64) {
    curl_easy_setopt(handle, option, value as std::ffi::c_long);
}

unsafe fn set_opt_ptr(handle: CURL, option: i32, value: *mut std::ffi::c_void) {
    curl_easy_setopt(handle, option, value);
}

/// A single libcurl easy handle.
pub struct Easy {
    handle: CURL,
    body: Box<Vec<u8>>,
    headers: Box<Vec<String>>,
    error_buffer: Box<[u8; CURL_ERROR_SIZE]>,
}

impl Drop for Easy {
    fn drop(&mut self) {
        unsafe { curl_easy_cleanup(self.handle) }
    }
}

impl Easy {
    pub fn new() -> Option<Easy> {
        let handle = unsafe { curl_easy_init() };
        if handle.is_null() {
            return None;
        }
        let mut easy = Easy {
            handle,
            body: Box::new(Vec::new()),
            headers: Box::new(Vec::new()),
            error_buffer: Box::new([0u8; CURL_ERROR_SIZE]),
        };
        unsafe {
            set_opt_ptr(easy.handle, CURLOPT_WRITEDATA, &mut *easy.body as *mut Vec<u8> as *mut std::ffi::c_void);
            set_opt_ptr(easy.handle, CURLOPT_HEADERDATA, &mut *easy.headers as *mut Vec<String> as *mut std::ffi::c_void);
            set_opt_ptr(easy.handle, CURLOPT_ERRORBUFFER, easy.error_buffer.as_mut_ptr() as *mut std::ffi::c_void);
            curl_easy_setopt(easy.handle, CURLOPT_WRITEFUNCTION, write_callback as extern "C" fn(*mut u8, usize, usize, *mut std::ffi::c_void) -> usize);
            curl_easy_setopt(easy.handle, CURLOPT_HEADERFUNCTION, header_callback as extern "C" fn(*mut u8, usize, usize, *mut std::ffi::c_void) -> usize);
            set_opt_long(easy.handle, CURLOPT_FOLLOWLOCATION, 0);
            curl_easy_setopt(easy.handle, CURLOPT_ACCEPT_ENCODING, std::ptr::null::<u8>());
        }
        Some(easy)
    }

    pub fn perform(&mut self, url: &str, defaults: &RequestDefaults) -> Response {
        unsafe {
            let mut list: *mut CurlSlist = std::ptr::null_mut();
            for header in defaults.headers.iter() {
                let c = std::ffi::CString::new(header.as_str()).unwrap_or_default();
                list = curl_slist_append(list, c.as_ptr());
            }
            for cookie in defaults.cookies.iter() {
                let value = format!("Cookie: {}", cookie);
                let c = std::ffi::CString::new(value).unwrap_or_default();
                list = curl_slist_append(list, c.as_ptr());
            }
            set_opt_ptr(self.handle, CURLOPT_HTTPHEADER, list as *mut std::ffi::c_void);
            self.body.clear();
            self.headers.clear();
            self.error_buffer = Box::new([0u8; CURL_ERROR_SIZE]);
            set_opt_str(self.handle, CURLOPT_URL, url);
            set_opt_long(self.handle, CURLOPT_TIMEOUT_MS, defaults.timeout_ms as i64);
            match defaults.verb {
                HttpVerb::Get => set_opt_long(self.handle, CURLOPT_HTTPGET, 1),
                HttpVerb::Head => set_opt_long(self.handle, CURLOPT_NOBODY, 1),
                HttpVerb::Post => {
                    set_opt_long(self.handle, CURLOPT_POST, 1);
                    set_opt_str(self.handle, CURLOPT_POSTFIELDS, "");
                }
            }
            if let Some(agent) = &defaults.user_agent {
                set_opt_str(self.handle, CURLOPT_USERAGENT, agent);
            }
            if defaults.ignore_cert {
                set_opt_long(self.handle, CURLOPT_SSL_VERIFYPEER, 0);
                set_opt_long(self.handle, CURLOPT_SSL_VERIFYHOST, 0);
            }
            if let Some(proxy) = &defaults.proxy {
                set_opt_str(self.handle, CURLOPT_PROXY, proxy);
            }
            let error = curl_easy_perform(self.handle);
            let code = self.code();
            if error != CurlError::Ok {
                let message = self.error_message(error);
                let _ = list;
                return Response {
                    url: url.to_string(),
                    code,
                    body: Vec::new(),
                    headers: Vec::new(),
                    location: None,
                    error: Some(CurlFailure { code: error, message }),
                };
            }
            let _ = list;
        }
        self.finish(url)
    }

    fn finish(&self, url: &str) -> Response {
        let location = self
            .headers
            .iter()
            .find_map(|h| {
                if let Some(rest) = h.strip_prefix("Location:") {
                    Some(rest.trim().to_string())
                } else {
                    None
                }
            });
        Response {
            url: url.to_string(),
            code: self.code(),
            body: self.body.clone(),
            headers: self.headers.clone(),
            location,
            error: None,
        }
    }

    pub fn code(&self) -> u16 {
        let mut code: u32 = 0;
        unsafe {
            curl_easy_getinfo(self.handle, CURLINFO_RESPONSE_CODE, &mut code as *mut u32);
        }
        code as u16
    }

    pub fn error_message(&self, code: CurlError) -> String {
        let detail = unsafe {
            let end = self.error_buffer.iter().position(|b| *b == 0).unwrap_or(0);
            String::from_utf8_lossy(&self.error_buffer[..end]).to_string()
        };
        let base = unsafe {
            let ptr = curl_easy_strerror(code);
            let len = std::ffi::c_char_len(ptr);
            String::from_utf8_lossy(std::ffi::c_char_bytes(ptr, len)).to_string()
        };
        if detail.is_empty() {
            base
        } else {
            format!("{} ({})", base, detail)
        }
    }
}
RSEOF
echo done; wc -l src/request.rs"}

