        unsafe {
            set_opt_ptr(easy.handle, CURLOPT_WRITEDATA, &mut *easy.body as *mut Vec<u8> as *mut std::ffi::c_void);
            set_opt_ptr(easy.handle, CURLOPT_HEADERDATA, &mut *easy.headers as *mut Vec<String> as *mut std::ffi::c_void);
            set_opt_ptr(easy.handle, CURLOPT_ERRORBUFFER, easy.error_buffer.as_mut_ptr() as *mut std::ffi::c_void);
            curl_easy_setopt(easy.handle, CURLOPT_WRITEFUNCTION, write_callback as extern "C" fn(*mut u8, usize, usize, *mut std::ffi::c_void) -> usize);
