        unsafe {
            let mut list: *mut CurlSlist = std::ptr::null_mut();
            for header in defaults.headers.iter() {
                let c = std::ffi::CString::new(header.as_str()).unwrap_or_default();
                list = curl_slist_append(list, c.as_ptr());
            }
            for cookie in defaults.cookies.iter() {
                let value = format!("Cookie: {}", cookie);
                let c = std::ffi::CString::new(value).unwrap_or_default();
                list = curl_slist_append(list, c.as_ptr());
            }
            set_opt_ptr(self.handle, CURLOPT_HTTPHEADER, list as *mut std::ffi::c_void);
            self.body.clear();
            self.headers.clear();
            self.error_buffer = Box::new([0u8; CURL_ERROR_SIZE]);
            set_opt_str(self.handle, CURLOPT_URL, url);
            set_opt_long(self.handle, CURLOPT_TIMEOUT_MS, defaults.timeout_ms as i64);
            match defaults.verb {
                HttpVerb::Get => set_opt_long(self.handle, CURLOPT_HTTPGET, 1),
                HttpVerb::Head => set_opt_long(self.handle, CURLOPT_NOBODY, 1),
                HttpVerb::Post => {
                    set_opt_long(self.handle, CURLOPT_POST, 1);
                    set_opt_str(self.handle, CURLOPT_POSTFIELDS, "");
                }
            }
            if let Some(agent) = &defaults.user_agent {
                set_opt_str(self.handle, CURLOPT_USERAGENT, agent);
            }
            if defaults.ignore_cert {
                set_opt_long(self.handle, CURLOPT_SSL_VERIFYPEER, 0);
                set_opt_long(self.handle, CURLOPT_SSL_VERIFYHOST, 0);
            }
            if let Some(proxy) = &defaults.proxy {
                set_opt_str(self.handle, CURLOPT_PROXY, proxy);
            }
            let error = curl_easy_perform(self.handle);
            let code = self.code();
            if error != CurlError::Ok {
                let message = self.error_message(error);
                let _ = list;
                return Response {
                    url: url.to_string(),
                    code,
                    body: Vec::new(),
                    headers: Vec::new(),
                    location: None,
                    error: Some(CurlFailure { code: error, message }),
                };
            }
            let _ = list;
        }
        self.finish(url)
    }

    fn finish(&self, url: &str) -> Response {
        let location = self
            .headers
            .iter()
            .find_map(|h| {
                if let Some(rest) = h.strip_prefix("Location:") {
                    Some(rest.trim().to_string())
                } else {
                    None
                }
            });
        Response {
            url: url.to_string(),
            code: self.code(),
            body: self.body.clone(),
            headers: self.headers.clone(),
            location,
            error: None,
        }
    }

    pub fn code(&self) -> u16 {
        let mut code: u32 = 0;
        unsafe {
            curl_easy_getinfo(self.handle, CURLINFO_RESPONSE_CODE, &mut code as *mut u32);
        }
        code as u16
    }

    pub fn error_message(&self, code: CurlError) -> String {
        let detail = unsafe {
            let end = self.error_buffer.iter().position(|b| *b == 0).unwrap_or(0);
            String::from_utf8_lossy(&self.error_buffer[..end]).to_string()
        };
        let base = unsafe {
            let ptr = curl_easy_strerror(code);
            let len = std::ffi::c_char_len(ptr);
            String::from_utf8_lossy(std::ffi::c_char_bytes(ptr, len)).to_string()
        };
        if detail.is_empty() {
            base
        } else {
            format!("{} ({})", base, detail)
        }
    }
}
