            );
            set_ptr(
                easy.handle,
                opt::ERRORBUFFER,
                easy.error.as_mut_ptr() as *mut std::ffi::c_void,
            );
            curl_easy_setopt(
                easy.handle,
                opt::WRITEFUNCTION,
                write_cb as extern "C" fn(*mut u8, usize, usize, *mut std::ffi::c_void) -> usize,
            );
