/// One libcurl easy handle that can be reused for many requests.
pub struct Easy {
    handle: CURL,
    body: Box<Vec<u8>>,
    headers: Box<Vec<String>>,
    error: Box<[u8; CURL_ERROR_SIZE]>,
}

impl Drop for Easy {
    fn drop(&mut self) {
        unsafe { curl_easy_cleanup(self.handle) }
    }
}

impl Default for Easy {
    fn default() -> Self {
        Self::new().expect("curl_easy_init failed")
    }
}

impl Easy {
    pub fn new() -> Option<Easy> {
        let handle = unsafe { curl_easy_init() };
        if handle.is_null() {
            return None;
        }
        let mut easy = Easy {
            handle,
            body: Box::new(Vec::new()),
            headers: Box::new(Vec::new()),
            error: Box::new([0u8; CURL_ERROR_SIZE]),
        };
        unsafe {
            set_ptr(
                easy.handle,
                opt::WRITEDATA,
                &mut *easy.body as *mut Vec<u8> as *mut std::ffi::c_void,
            );
            set_ptr(
                easy.handle,
                opt::HEADERDATA,
                &mut *easy.headers as *mut Vec<String> as *mut std::ffi::c_void,
            );
            set_ptr(
                easy.handle,
                opt::ERRORBUFFER,
                easy.error.as_mut_ptr() as *mut std::ffi::c_void,
            );
            curl_easy_setopt(
                easy.handle,
                opt::WRITEFUNCTION,
                write_cb as extern "C" fn(*mut u8, usize, usize, *mut std::ffi::c_void) -> usize,
            );
            curl_easy_setopt(
                easy.handle,
                opt::HEADERFUNCTION,
                header_cb as extern "C" fn(*mut u8, usize, usize, *mut std::ffi::c_void) -> usize,
            );
            set_long(easy.handle, opt::FOLLOWLOCATION, 0);
            curl_easy_setopt(easy.handle, opt::ACCEPT_ENCODING as i32, std::ptr::null::<u8>());
        }
        Some(easy)
    }

    /// Sends one request and returns the parsed response.
    pub fn perform(&mut self, url: &str, defaults: &Defaults) -> Response {
        trace!("Requesting {}", url);
        unsafe {
            let mut list: *mut Slist = std::ptr::null_mut();
            for header in defaults.headers.iter() {
                let c = cstr(header);
                list = curl_slist_append(list, c.as_ptr());
            }
            for cookie in defaults.cookies.iter() {
                let value = format!("Cookie: {}", cookie);
                let c = cstr(&value);
                list = curl_slist_append(list, c.as_ptr());
            }
            set_ptr(self.handle, opt::HTTPHEADER, list as *mut std::ffi::c_void);
            self.body.clear();
            self.headers.clear();
            self.error = Box::new([0u8; CURL_ERROR_SIZE]);
            set_str(self.handle, opt::URL, url);
            set_long(self.handle, opt::TIMEOUT_MS, defaults.timeout_ms as i64);
            match defaults.verb {
                HttpVerb::Get => set_long(self.handle, opt::HTTPGET, 1),
                HttpVerb::Head => set_long(self.handle, opt::NOBODY, 1),
                HttpVerb::Post => {
                    set_long(self.handle, opt::POST, 1);
                    set_str(self.handle, opt::POSTFIELDS, "");
                }
            }
            if let Some(agent) = &defaults.user_agent {
                set_str(self.handle, opt::USERAGENT, agent);
            }
            if defaults.ignore_cert {
                set_long(self.handle, opt::SSL_VERIFYPEER, 0);
                set_long(self.handle, opt::SSL_VERIFYHOST, 0);
            }
            if let Some(proxy) = &defaults.proxy {
                set_str(self.handle, opt::PROXY, proxy);
            }
            if let Some(credentials) = &defaults.credentials {
                set_str(self.handle, opt::USERPWD, credentials);
            }
            let status = curl_easy_perform(self.handle);
            if status != 0 {
                let failure = CurlFailure {
                    code: status,
                    message: self.describe(status),
                };
                curl_slist_free_all(list);
                return Response {
                    url: url.to_string(),
                    code: self.code(),
                    body: Vec::new(),
                    headers: Vec::new(),
                    location: None,
                    failure: Some(failure),
                };
            }
            curl_slist_free_all(list);
        }
        self.finish(url)
    }

    /// Builds the response from the collected body and headers.
    fn finish(&self, url: &str) -> Response {
        let location = self.headers.iter().find_map(|h| {
            if let Some(rest) = h.strip_prefix("Location:") {
                Some(rest.trim().to_string())
            } else {
                None
            }
        });
        Response {
            url: url.to_string(),
            code: self.code(),
            body: self.body.clone(),
            headers: self.headers.clone(),
            location,
            failure: None,
        }
    }

    fn code(&self) -> u16 {
        let mut code: u32 = 0;
        unsafe {
            curl_easy_getinfo(self.handle, info::RESPONSE_CODE, &mut code as *mut u32);
        }
        code as u16
    }

    /// Combines the libcurl error code with the extra detail from the buffer.
    pub fn describe(&self, code: i32) -> String {
        let detail = unsafe {
            let end = self.error.iter().position(|b| *b == 0).unwrap_or(0);
            String::from_utf8_lossy(&self.error[..end]).to_string()
        };
        let base = unsafe {
            let ptr = curl_easy_strerror(code);
            from_cstr(ptr)
        };
        if detail.is_empty() {
            base
        } else {
            format!("{} ({})", base, detail)
        }
    }
}
