//! Report generation.
//!
//! Three output formats are supported: a plain text report, a JSON array and a
//! small XML document.  All three are produced from the same collection of
//! [`FoundPath`] values and share the same ordering rules.

/// A single path that the scanner decided to report.
#[derive(Clone, Debug)]
pub struct FoundPath {
    pub base: String,
    pub url: String,
    pub code: u16,
    pub size: usize,
    pub is_directory: bool,
    pub is_listable: bool,
    pub redirect_url: String,
    pub found_from_listable: bool,
}

impl FoundPath {
    /// The marker that starts the console line.
    pub fn marker(&self) -> char {
        if self.is_listable {
            'L'
        } else if self.is_directory {
            'D'
        } else {
            '+'
        }
    }

    /// The parenthesised part that follows the url.
    pub fn detail(&self) -> String {
        if self.is_directory && self.size == 0 && self.code == 0 {
            return "SCRAPED".to_string();
        }
        let mut detail = format!("CODE:{}|SIZE:{}", self.code, self.size);
        if !self.redirect_url.is_empty() {
            detail.push_str(&format!("|DEST:{}", self.redirect_url));
        }
        detail
    }

    /// The line as it appears on the console and in the text report.
    pub fn line(&self) -> String {
        format!("{} {} ({})", self.marker(), self.url, self.detail())
    }
}

/// Groups the results by the directory that contains them.
///
/// The groups are ordered by their directory url and the entries inside every
/// group are ordered by their own url.
fn group_by_directory(paths: &[FoundPath]) -> Vec<(String, Vec<&FoundPath>)> {
    let mut order: Vec<String> = Vec::new();
    let mut groups: std::collections::HashMap<String, Vec<&FoundPath>> =
        std::collections::HashMap::new();
    for path in paths {
        let parent = parent_of(&path.url);
        if !groups.contains_key(&parent) {
            order.push(parent.clone());
            groups.insert(parent.clone(), Vec::new());
        }
        groups.get_mut(&parent).unwrap().push(path);
    }
    let mut result: Vec<(String, Vec<&FoundPath>)> = Vec::new();
    for key in order {
        if let Some(items) = groups.remove(&key) {
            result.push((key, items));
        }
    }
    result
}

/// Returns the url of the directory holding `url`.
fn parent_of(url: &str) -> String {
    match url.rfind('/') {
        Some(index) if index > 0 => url[..index].to_string(),
        _ => url.to_string(),
    }
}

/// Renders the plain text report for one uri.
pub fn text_report(base: &str, paths: &[FoundPath]) -> String {
    let mut out = format!("Dirble Scan Report for {}:\n", base);
    for (_, group) in group_by_directory(paths) {
        let mut items: Vec<&FoundPath> = group;
        items.sort_by(|a, b| a.url.cmp(&b.url));
        for item in items {
            out.push_str(&item.line());
            out.push('\n');
        }
        out.push('\n');
    }
    out
}

/// Renders the JSON report for one uri.
pub fn json_report(paths: &[FoundPath]) -> String {
    let mut out = String::new();
    let mut items: Vec<&FoundPath> = paths.iter().collect();
    items.sort_by(|a, b| a.url.cmp(&b.url));
    for (index, item) in items.iter().enumerate() {
        if index > 0 {
            out.push_str(",\n");
        }
        out.push_str(&json_item(item));
    }
    format!("[{}]", out)
}

fn json_string(value: &str) -> String {
    let mut out = String::from("\"");
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            _ => out.push(ch),
        }
    }
    out.push('"');
    out
}

fn json_item(item: &FoundPath) -> String {
    format!(
        "{{\"url\":{},\"code\":{},\"size\":{},\"is_directory\":{},\"is_listable\":{},\"redirect_url\":{},\"found_from_listable\":{}}}",
        json_string(&item.url),
        item.code,
        item.size,
        item.is_directory,
        item.is_listable,
        json_string(&item.redirect_url),
        item.found_from_listable
    )
}

/// Renders the XML report for one uri.
pub fn xml_report(paths: &[FoundPath]) -> String {
    let mut out = String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<dirble_scan>\n");
    let mut items: Vec<&FoundPath> = paths.iter().collect();
    items.sort_by(|a, b| a.url.cmp(&b.url));
    for item in items {
        out.push_str(&xml_item(item));
    }
    out.push_str("</dirble_scan>");
    out
}

fn xml_escape(value: &str) -> String {
    let mut out = String::new();
    for ch in value.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(ch),
        }
    }
    out
}

fn xml_item(item: &FoundPath) -> String {
    format!(
        "<path url=\"{}\" code=\"{}\" content_len=\"{}\" is_directory=\"{}\" is_listable=\"{}\" redirect_url=\"{}\" found_from_listable=\"{}\"/>\n",
        xml_escape(&item.url),
        item.code,
        item.size,
        item.is_directory,
        item.is_listable,
        xml_escape(&item.redirect_url),
        item.found_from_listable
    )
}
