//! Extraction of urls from directory listings.
//!
//! The response body of a listable directory is parsed as HTML and every
//! `href` attribute of an `<a>` element is collected.  The body is lower cased
//! before parsing which is what makes the extraction insensitive to the case
//! that the server used.

/// Collects the `href` values of all `<a>` elements in `body`.
///
/// The body is expected to already be lower cased.  Character references are
/// decoded the way an HTML5 parser would do it.
pub fn extract_hrefs(body: &str) -> Vec<String> {
    let lower = body.to_lowercase();
    let mut out = Vec::new();
    let bytes = lower.as_bytes();
    let mut index = 0usize;
    while index < bytes.len() {
        if bytes[index] == b'<' {
            if let Some((tag_end, is_anchor, href)) = parse_tag(&lower, index) {
                if is_anchor {
                    if let Some(value) = href {
                        out.push(decode_entities(&value));
                    }
                }
                index = tag_end;
                continue;
            }
        }
        index += 1;
    }
    out
}

/// Parses one tag starting at `start`.
///
/// Returns the index just after the tag, whether it was an `<a>` start tag and
/// the value of its `href` attribute when present.
fn parse_tag(text: &str, start: usize) -> Option<(usize, bool, Option<String>)> {
    let bytes = text.as_bytes();
    let mut index = start + 1;
    if index >= bytes.len() {
        return None;
    }
    // A closing tag never carries attributes.
    if bytes[index] == b'/' || bytes[index] == b'!' || bytes[index] == b'?' {
        while index < bytes.len() && bytes[index] != b'>' {
            index += 1;
        }
        return Some((index + 1, false, None));
    }
    let name_start = index;
    while index < bytes.len() && is_name_byte(bytes[index]) {
        index += 1;
    }
    let name = &text[name_start..index];
    let is_anchor = name == "a";
    let mut href: Option<String> = None;
    while index < bytes.len() {
        while index < bytes.len() && (bytes[index] as char).is_whitespace() {
            index += 1;
        }
        if index >= bytes.len() {
            break;
        }
        if bytes[index] == b'>' {
            return Some((index + 1, is_anchor, href));
        }
        if bytes[index] == b'/' {
            index += 1;
            continue;
        }
        let attr_start = index;
        while index < bytes.len() && is_name_byte(bytes[index]) {
            index += 1;
        }
        let attr_name = &text[attr_start..index];
        let mut cursor = index;
        while cursor < bytes.len() && (bytes[cursor] as char).is_whitespace() {
            cursor += 1;
        }
        let mut value: Option<String> = None;
        if cursor < bytes.len() && bytes[cursor] == b'=' {
            cursor += 1;
            while cursor < bytes.len() && (bytes[cursor] as char).is_whitespace() {
                cursor += 1;
            }
            if cursor < bytes.len() && (bytes[cursor] == b'"' || bytes[cursor] == b'\'') {
                let quote = bytes[cursor];
                cursor += 1;
                let value_start = cursor;
                while cursor < bytes.len() && bytes[cursor] != quote {
                    cursor += 1;
                }
                value = Some(text[value_start..cursor].to_string());
                if cursor < bytes.len() {
                    cursor += 1;
                }
            } else {
                let value_start = cursor;
                while cursor < bytes.len()
                    && !(bytes[cursor] as char).is_whitespace()
                    && bytes[cursor] != b'>'
                {
                    cursor += 1;
                }
                value = Some(text[value_start..cursor].to_string());
            }
        }
        index = cursor;
        if is_anchor && attr_name == "href" && href.is_none() {
            href = value;
        }
    }
    Some((bytes.len(), is_anchor, href))
}

fn is_name_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'-' || byte == b'_' || byte == b':'
}

/// Decodes the character references that can appear in an attribute value.
fn decode_entities(value: &str) -> String {
    if !value.contains('&') {
        return value.to_string();
