//! Detection of the response that a server returns for paths that do not
//! exist.
//!
//! Three random paths are requested.  The response code that appears at least
//! twice is used as the "not found" marker; when no code repeats the scanner
//! falls back to a plain 404.

use crate::arg_parse::Config;
use crate::request::{Defaults, Easy};
use rand::Rng;
use std::sync::mpsc::{channel, Receiver, Sender};

/// The characters that random probe paths are built from.
const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

/// The lengths of the three probe paths.
const PROBE_LENGTHS: [usize; 3] = [10, 20, 30];

/// The response that the server gives for a path that does not exist.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NotFound {
    pub code: u16,
    pub size: usize,
}

impl NotFound {
    /// The text used in the informational message.
    pub fn describe(&self) -> String {
        if self.code == 404 {
            format!("CODE:{}", self.code)
        } else {
            format!("CODE:{}|SIZE:{}", self.code, self.size)
        }
    }

    /// Whether a response matches this "not found" signature.
    pub fn matches(&self, code: u16, size: usize) -> bool {
        self.code == code && (self.code == 404 || self.size == size)
    }
}

/// The default signature used when the probe requests do not agree.
fn default_not_found() -> NotFound {
    NotFound { code: 404, size: 0 }
}

/// Builds a random path of the given length.
fn random_path(len: usize) -> String {
    let mut rng = rand::thread_rng();
    (0..len)
        .map(|_| ALPHABET[rng.gen_range(0..ALPHABET.len())] as char)
        .collect()
}

/// Performs the probe requests and derives the not found signature.
pub fn detect(url: &str, defaults: &Defaults, config: &Config) -> NotFound {
    let mut easy = match Easy::new() {
        Some(easy) => easy,
        None => return default_not_found(),
    };
    let mut codes: Vec<(u16, usize)> = Vec::new();
    for len in PROBE_LENGTHS.iter() {
        let probe = format!("{}{}", url, random_path(*len));
        let response = easy.perform(&probe, defaults);
        if let Some(failure) = &response.failure {
            crate::output_thread::print_curl_error(&probe, failure);
            continue;
        }
        codes.push((response.code, response.size()));
    }
    if config.silent || config.disable_validator {
        return default_not_found();
    }
    let signature = majority(&codes);
    if !config.silent {
        crate::output_thread::print_not_found(url, &signature);
    }
    signature
}

/// Picks the code that appeared at least twice, if any.
fn majority(codes: &[(u16, usize)]) -> NotFound {
    for (index, (code, size)) in codes.iter().enumerate() {
        if codes[index + 1..].iter().any(|(other, _)| other == code) {
            return NotFound {
                code: *code,
                size: *size,
            };
        }
    }
    default_not_found()
}

/// Handle to the single thread that performs the probe requests.
pub struct Validator {
    tx: Sender<String>,
    rx: Receiver<NotFound>,
}

impl Validator {
    /// Starts the validator thread.
    pub fn start(defaults: Defaults, config: std::sync::Arc<Config>) -> Validator {
        let (tx, work): (Sender<String>, Receiver<String>) = channel();
        let (done, rx): (Sender<NotFound>, Receiver<NotFound>) = channel();
        std::thread::spawn(move || {
            while let Ok(url) = work.recv() {
                let _ = done.send(detect(&url, &defaults, &config));
            }
        });
        Validator { tx, rx }
    }

    /// Asks the validator thread for the signature of `url`.
    pub fn detect(&self, url: &str) -> NotFound {
        if self.tx.send(url.to_string()).is_err() {
            return default_not_found();
        }
        self.rx.recv().unwrap_or_else(|_| default_not_found())
    }
}
