//! The worker that turns scan items into requests and reports.
//!
//! Each worker owns a slice of the wordlist for one folder/extension combo.
//! It acquires a thread slot for its whole lifetime, walks its items in order
//! and reports everything it finds to the output thread.  Directories that are
//! discovered on the way are handed over to the coordinator so that they can be
//! scanned as well.

use crate::arg_parse::{Config, HttpVerb};
use crate::report::FoundPath;
use crate::request::{Defaults, Easy, Response};
use crate::scan::{Engine, ScanItem};
use crate::url::Url;
use log::{debug, trace};
use std::sync::Arc;

/// The maximum number of consecutive errors a worker tolerates.
fn max_errors(config: &Config) -> usize {
    config.max_errors
}

/// Whether the response should be shown to the user.
fn showable(config: &Config, item: &ScanItem, code: u16) -> bool {
    if !config.code_whitelist.is_empty() {
        return config.code_whitelist.contains(&code);
    }
    if config.code_blacklist.contains(&code) {
        return false;
    }
    if code == 403 && !config.show_htaccess && item.url.contains(".ht") {
        return false;
