            is_directory: true,
            is_listable: false,
            redirect_url: String::new(),
            found_from_listable: false,
        };
        self.engine.send(path);
    }

    #[allow(clippy::too_many_arguments)]
    fn report(
        &self,
        _item: &ScanItem,
        url: &str,
        code: u16,
        size: usize,
        is_directory: bool,
        is_listable: bool,
        redirect_url: String,
    ) {
        let path = FoundPath {
            base: self.engine.base_string(),
            url: url.to_string(),
            code,
            size,
            is_directory,
            is_listable,
            redirect_url,
            found_from_listable: false,
        };
        self.engine.send(path);
    }

    fn record_failure(&self, url: &str, failure: &crate::request::CurlFailure) {
        crate::output_thread::print_curl_error(url, failure);
        self.engine.note_error(url);
    }

    /// Follows the links of a listable directory response.
    fn scrape(&mut self, url: &str, depth: usize) {
        let body = match self.easy.last_body() {
            Some(body) => body,
            None => return,
        };
        for href in crate::scrape::extract_hrefs(&body) {
            let base = self.engine.base();
            let joined = base.join(&href);
            let target = joined.to_string();
            if !target.ends_with('/') {
                trace!("[{}]: code 0 detected", target);
                continue;
            }
            let item = ScanItem {
                url: target,
                depth: depth + crate::scan::segments_added(url, &target),
                is_directory_hint: true,
                is_scraped: true,
                code: 1,
            };
            self.handle(item);
        }
    }
}
