//! Collects the results of a scan and produces the user visible output.
//!
//! Everything the user sees is written by a single thread so that the console
//! output stays readable while the request threads are running.  Once the scan
//! has finished the same thread writes the requested report files.

use crate::report::{json_report, text_report, xml_report, FoundPath};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::Arc;

use crate::arg_parse::Config;

/// Messages that the output thread understands.
pub enum Message {
    /// A path that should be reported.
    Found(FoundPath),
    /// An informational message.
    Info(String),
    /// A warning message.
    Warn(String),
    /// A libcurl failure.
    CurlError { url: String, message: String },
    /// The scan is over.
    Finish,
}

/// Starts the output thread and returns the sending side of its channel.
pub fn start(config: Arc<Config>) -> Sender<Message> {
    let (tx, rx): (Sender<Message>, Receiver<Message>) = channel();
    std::thread::spawn(move || run(rx, config));
    tx
}

fn run(rx: Receiver<Message>, config: Arc<Config>) {
    let mut paths: Vec<FoundPath> = Vec::new();
    let mut bases: Vec<String> = Vec::new();
    for message in rx {
        match message {
            Message::Found(path) => {
                if !bases.contains(&path.base) {
                    bases.push(path.base.clone());
                }
                if !config.silent {
                    println!("{}", path.line());
                }
                paths.push(path);
            }
            Message::Info(text) => {
                if !config.silent {
                    println!("[INFO] {}", text);
                }
            }
            Message::Warn(text) => {
                println!("[WARN] {}", text);
            }
            Message::CurlError { url, message } => {
                println!("Curl error after requesting {} : {}", url, message);
            }
            Message::Finish => break,
        }
    }
    debug!("Received signal to end, generating the report");
    write_reports(&config, &bases, &paths);
}

fn write_reports(config: &Config, bases: &[String], paths: &[FoundPath]) {
    let mut targets: Vec<(Option<String>, Option<String>, Option<String>)> = Vec::new();
    if let Some(all) = &config.output_all {
        targets.push((
            Some(format!("{}.txt", all)),
            Some(format!("{}.json", all)),
            Some(format!("{}.xml", all)),
        ));
    }
    if config.output_file.is_some() || config.json_file.is_some() || config.xml_file.is_some() {
        targets.push((
            config.output_file.clone(),
            config.json_file.clone(),
            config.xml_file.clone(),
        ));
    }
    for (txt, json, xml) in targets {
        let mut text = String::new();
        for base in bases {
            let mine: Vec<&FoundPath> = paths.iter().filter(|p| &p.base == base).collect();
            let owned: Vec<FoundPath> = mine.into_iter().cloned().collect();
            text.push_str(&text_report(base, &owned));
        }
        if let Some(path) = txt {
            let _ = std::fs::write(path, text);
        }
        if let Some(path) = json {
            let _ = std::fs::write(path, json_report(&owned_all(paths)));
        }
        if let Some(path) = xml {
            let _ = std::fs::write(path, xml_report(&owned_all(paths)));
        }
    }
}

fn owned_all(paths: &[FoundPath]) -> Vec<FoundPath> {
    paths.to_vec()
}

/// Prints an informational message from any thread.
pub fn print_info(sender: &Sender<Message>, text: String) {
    let _ = sender.send(Message::Info(text));
}

/// Prints a warning message from any thread.
pub fn print_warn(sender: &Sender<Message>, text: String) {
    let _ = sender.send(Message::Warn(text));
}

/// Prints a libcurl failure from any thread.
pub fn print_curl_error(url: &str, failure: &crate::request::CurlFailure) {
    let text = format!("Curl error after requesting {} : [{}] {}", url, failure.code, failure.message);
    crate::log_bridge::emit(text);
}

/// Prints the detected not found signature.
pub fn print_not_found(url: &str, signature: &crate::validator::NotFound) {
    let text = format!(
        "Detected nonexistent paths for {} are ({})",
        url,
        signature.describe()
    );
    crate::log_bridge::emit(text);
}
