//! Bridge between the log crate and the output channel.
//!
//! Log records that belong to the scanner itself are routed to the output
//! thread so that they honour the `--silent` flag.  Everything else (records
//! coming from dependencies) is written directly to stdout.

use std::sync::mpsc::Sender;
use std::sync::{Arc, Mutex};

thread_local! {
    static SENDER: Option<Arc<Mutex<Sender<crate::output_thread::Message>>>> = None;
}

static GLOBAL: Mutex<Option<Arc<Mutex<Sender<crate::output_thread::Message>>>>> =
    Mutex::new(None);

/// Stores the sender used for scanner generated messages.
pub fn set_sender(sender: Arc<Mutex<Sender<crate::output_thread::Message>>>) {
    *GLOBAL.lock().unwrap() = Some(sender);
}

/// Writes a scanner message either through the output thread or directly.
pub fn emit(text: String) {
    let handled = {
        let guard = GLOBAL.lock().unwrap();
        match &*guard {
            Some(sender) => {
                let lock = sender.lock().unwrap();
                let _ = lock.send(crate::output_thread::Message::Info(text));
                true
            }
            None => false,
        }
    };
    if !handled {
        println!("{}", text);
    }
}
