//! Minimal logger producing the same layout as the original tool.
//!
//! ```text
//! 12:00:00 [DEBUG] (5) dirble::request_thread: Scanning http://host/
//! ```
//!
//! The level is controlled by the number of `-v` flags: none selects `info`,
//! one selects `debug` and two or more select `trace`.

use log::{Level, LevelFilter, Metadata, Record};
use std::sync::atomic::{AtomicUsize, Ordering};

static LEVEL: AtomicUsize = AtomicUsize::new(3);

/// Installs the logger for this process.
pub fn init(verbose: u8) {
    let filter = match verbose {
        0 => LevelFilter::Info,
        1 => LevelFilter::Debug,
        _ => LevelFilter::Trace,
    };
    LEVEL.store(filter as usize, Ordering::Relaxed);
    let _ = log::set_boxed_logger(Box::new(Bridge));
    log::set_max_level(filter);
}

struct Bridge;

impl log::Log for Bridge {
    fn enabled(&self, metadata: &Metadata) -> bool {
        metadata.level() as usize <= LEVEL.load(Ordering::Relaxed)
    }

    fn log(&self, record: &Record) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let level = match record.level() {
            Level::Error => "ERROR",
            Level::Warn => "WARN",
            Level::Info => "INFO",
            Level::Debug => "DEBUG",
            Level::Trace => "TRACE",
        };
        let thread = std::thread::current();
        let id = thread_id(&thread);
        let target = record.target().unwrap_or("");
        let location = match (record.file(), record.line()) {
            (Some(file), Some(line)) => format!("[{}:{}] ", file, line),
            _ => String::new(),
        };
        println!(
            "{} [{}] ({}) {}: {}{}",
            timestamp(),
            level,
            id,
            target,
            location,
            record.args()
        );
    }

    fn flush(&self) {}
}

/// The numeric part of the runtime thread identifier.
fn thread_id(thread: &std::thread::Thread) -> String {
    let text = format!("{:?}", thread.id());
    match text.find('(') {
        Some(start) => text[start + 1..text.len() - 1].to_string(),
        None => text,
    }
}

/// Formats the current UTC time as `HH:MM:SS`.
fn timestamp() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let day = secs % 86_400;
    format!("{:02}:{:02}:{:02}", day / 3600, (day % 3600) / 60, day % 60)
}
RSEOF
echo ok"}

