use crate::url::Url;
use std::collections::{HashMap, HashSet, VecDeque};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::sync::mpsc::Sender;

use crate::output_thread::Message;
use crate::validator::{NotFound, Validator};

/// One unit of work for a request thread.
#[derive(Clone, Debug)]
pub struct ScanItem {
    pub url: String,
    pub depth: usize,
    pub is_directory_hint: bool,
    pub is_scraped: bool,
    pub code: u16,
}

/// A directory that still has to be validated and scanned.
#[derive(Clone, Debug)]
pub struct PendingDir {
    pub url: String,
    pub depth: usize,
}

/// Counts the path segments of a url.
pub fn segment_count(url: &str) -> usize {
    match Url::parse(url) {
        Ok(parsed) => parsed
            .path()
            .split('/')
            .filter(|s| !s.is_empty())
            .count(),
        Err(_) => 0,
    }
}

/// The number of path segments that `target` adds on top of `parent`.
pub fn segments_added(parent: &str, target: &str) -> usize {
    let parent_len = segment_count(parent);
    let target_len = segment_count(target);
    target_len.saturating_sub(parent_len)
}

/// A simple counting semaphore used to limit the number of concurrent requests.
pub struct Slots {
    state: Mutex<usize>,
    cond: Condvar,
}

impl Slots {
    pub fn new(count: usize) -> Slots {
        Slots {
            state: Mutex::new(count),
            cond: Condvar::new(),
        }
    }

    pub fn acquire(&self) {
        let mut guard = self.state.lock().unwrap();
        while *guard == 0 {
            guard = self.cond.wait(guard).unwrap();
        }
        *guard -= 1;
    }

    pub fn release(&self) {
        let mut guard = self.state.lock().unwrap();
        *guard += 1;
        self.cond.notify_one();
    }
}

/// Everything the workers need to know about the scan in progress.
pub struct Engine {
    pub config: Arc<Config>,
    pub defaults: Defaults,
    pub base: Url,
    pub base_string: String,
    pub slots: Arc<Slots>,
    pub results: Sender<Message>,
    pub validator: Arc<Validator>,
    pub wordlist: Vec<String>,
    pub signature: NotFound,
    pub recursion_limit: usize,
    pub pending: Mutex<VecDeque<PendingDir>>,
    pub active: AtomicUsize,
    pub condition: Condvar,
}

impl Engine {
    pub fn base(&self) -> &Url {
        &self.base
    }

    pub fn base_string(&self) -> String {
        self.base_string.clone()
    }

    pub fn recursion_limit(&self) -> usize {
        self.recursion_limit
    }

    pub fn not_found(&self) -> NotFound {
        self.signature
    }

    pub fn send(&self, path: FoundPath) {
        let _ = self.results.send(Message::Found(path));
    }

    pub fn info(&self, text: String) {
        let _ = self.results.send(Message::Info(text));
    }

    pub fn warn(&self, text: String) {
        let _ = self.results.send(Message::Warn(text));
    }

    /// Queues a directory for validation and recursive scanning.
    pub fn queue_recursion(&self, item: &ScanItem) {
        if self.config.disable_recursion {
            return;
        }
        let depth = segment_count(&item.url);
        if depth > self.recursion_limit {
            return;
        }
        let mut guard = self.pending.lock().unwrap();
        guard.push_back(PendingDir {
            url: item.url.clone(),
            depth,
        });
        self.condition.notify_one();
    }

    /// Waits for a directory to recurse into.
    pub fn next_pending(&self, active: usize) -> Option<PendingDir> {
        let mut guard = self.pending.lock().unwrap();
        loop {
            if let Some(dir) = guard.pop_front() {
                return Some(dir);
            }
            if active == 0 {
                return None;
            }
            guard = self.condition.wait(guard).unwrap();
        }
    }

    pub fn notify_done(&self) {
        self.condition.notify_one();
    }
}

/// Splits `items` into `count` chunks using round robin distribution.
pub fn deal<T: Clone>(items: &[T], count: usize) -> Vec<Vec<T>> {
    let mut chunks: Vec<Vec<T>> = (0..count).map(|_| Vec::new()).collect();
    for (index, item) in items.iter().enumerate() {
        chunks[index % count].push(item.clone());
    }
    chunks
}

/// Builds the list of prefix/extension combinations to scan.
pub fn combinations(config: &Config) -> Vec<(String, String)> {
    let mut prefixes: Vec<String> = Vec::new();
    if !config.prefixes.is_empty() {
        let mut unique: Vec<String> = config.prefixes.clone();
        unique.sort();
        unique.dedup();
        prefixes.extend(unique);
    }
    let mut extensions: Vec<String> = Vec::new();
    if !config.extensions.is_empty() {
        let mut unique: Vec<String> = config.extensions.clone();
        unique.sort();
        unique.dedup();
        extensions.extend(unique);
    }
    if !config.force_extension {
        extensions.insert(0, String::new());
    }
    if prefixes.is_empty() {
        prefixes.push(String::new());
    }
    let mut out = Vec::new();
    for prefix in &prefixes {
        for extension in &extensions {
            out.push((prefix.clone(), extension.clone()));
        }
    }
    out
}

/// Transforms a wordlist entry for one combination.
pub fn transform(word: &str, prefix: &str, extension: &str, ext_sub: bool) -> String {
    let mut text = if ext_sub {
        word.replace("%EXT%", extension)
    } else {
        format!("{}{}", word, extension)
    };
    text.insert_str(0, prefix);
    text
}

/// Removes one leading and one trailing slash from a wordlist entry.
pub fn normalize(line: &str) -> String {
    let trimmed = line.strip_prefix('/').unwrap_or(line);
    trimmed.strip_suffix('/').unwrap_or(trimmed).to_string()
}

/// Loads the wordlist: one entry per line, normalised, deduplicated and sorted.
pub fn load_wordlist(path: &str) -> Vec<String> {
    let data = std::fs::read_to_string(path).unwrap_or_default();
    let mut words: Vec<String> = data.lines().map(normalize).collect();
    let mut seen: HashSet<String> = HashSet::new();
    words.retain(|w| seen.insert(w.clone()));
    words.sort();
    words
}
