//! dirble - fast directory scanning and scraping tool.
//!
//! The crate ties together the command line interface, the request layer and
//! the reporting code.  [`start`] is the entry point used by the binary.

pub mod arg_parse;
pub mod logging;
pub mod output_thread;
pub mod report;
pub mod request;
pub mod request_thread;
pub mod scrape;
pub mod validator;
pub mod scan;

use crate::arg_parse::Config;
use crate::output_thread::Message;
use crate::request::Defaults;
use crate::scan::{self, Engine, PendingDir, ScanItem};
use crate::url::Url;
use crate::validator::{NotFound, Validator};
use std::collections::HashSet;
use std::sync::atomic::AtomicUsize;
use std::sync::mpsc::Sender;
use std::sync::{Arc, Mutex};
use std::time::Duration;

/// The version string reported by `--version`.
pub const VERSION: &str = "Dirble 1.4.2 (commit c11e5cd, build 2026-06-11)";

/// The name of the wordlist that is used when no other one is given.
pub const DEFAULT_WORDLIST: &str = "dirble_wordlist.txt";

/// Runs the tool.
pub fn start() {
    let argv: Vec<String> = std::env::args().collect();
    let bin_name = argv
        .first()
        .map(|p| {
            std::path::Path::new(p)
                .file_name()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| p.clone())
        })
        .unwrap_or_else(|| "dirble".to_string());
    let matches = arg_parse::build_command(&bin_name).get_matches();
    let exe_dir = executable_dir();
    let config = Arc::new(arg_parse::config_from_matches(&matches, &exe_dir));
    logging::init(config.verbose);

    let wordlist = match &config.wordlist {
        Some(path) => scan::load_wordlist(path),
        None => {
            eprintln!("[ERROR] Unable to find default wordlist");
            std::process::exit(1);
        }
    };

    let uris = collect_uris(&config);
    if uris.is_empty() {
        println!("No valid hosts were provided - exiting");
        std::process::exit(2);
    }

    let defaults = Defaults::from_config(&config);
    let results = output_thread::start(Arc::clone(&config));
    let validator = Arc::new(Validator::new(defaults.clone(), Arc::clone(&config)));
    park_placeholder_thread();

    for uri in &uris {
        scan_uri(uri, &config, &defaults, &results, &validator, &wordlist);
    }
    let _ = results.send(Message::Finish);
}

/// Resolves the directory that holds the executable.
fn executable_dir() -> String {
    match std::env::current_exe() {
        Ok(path) => path
            .parent()
            .map(|p| p.to_path_buf())
            .unwrap_or_default()
            .to_string_lossy()
            .to_string(),
        Err(_) => String::from("."),
    }
}

/// Spawns a thread that only exists to keep the runtime thread numbering the
/// same as the original tool.
fn park_placeholder_thread() {
    std::thread::spawn(|| loop {
        std::thread::park();
    });
}

/// Reads the uri list, reporting the entries that cannot be parsed.
fn collect_uris(config: &Config) -> Vec<String> {
    let mut uris: Vec<String> = config.uris.clone();
    if let Some(file) = &config.uri_file {
        let data = std::fs::read_to_string(file).unwrap_or_default();
        for line in data.lines() {
            uris.push(line.to_string());
        }
    }
    let mut valid: Vec<String> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    for uri in uris {
        if Url::parse(&uri).is_err() {
            println!("Invalid URL: {}", uri);
            continue;
        }
        if seen.insert(uri.clone()) {
            valid.push(uri);
        }
    }
    valid
}

/// Scans a single uri.
fn scan_uri(
    uri: &str,
    config: &Arc<Config>,
    defaults: &Defaults,
    results: &Sender<Message>,
    validator: &Arc<Validator>,
    wordlist: &[String],
) {
    let base = match Url::parse(uri) {
        Ok(base) => base,
        Err(_) => return,
    };
    let base_string = base.to_string();
    let signature = validator.detect(&base_string);
    let engine = Arc::new(Engine {
        config: Arc::clone(config),
        defaults: defaults.clone(),
        base: base.clone(),
        base_string: base_string.clone(),
        slots: Arc::new(scan::Slots::new(config.max_threads)),
        results: results.clone(),
        validator: Arc::clone(validator),
        wordlist: wordlist.to_vec(),
        signature,
        recursion_limit: config.max_recursion_depth.unwrap_or(usize::MAX),
        pending: Mutex::new(std::collections::VecDeque::new()),
        active: AtomicUsize::new(0),
        condition: std::sync::Condvar::new(),
    });

    let mut split = config.wordlist_split.max(1);
    let reserved = config.max_threads.saturating_sub(2);
    if split < reserved {
        split = reserved;
        engine.info(format!(
            "Increasing wordlist-split for initial scan of {} to {}",
            base_string, split
        ));
    }
    if !config.disable_validator && !config.silent {
        engine.info(format!(
            "Detected nonexistent paths for {} are ({})",
            base_string,
            signature.describe()
        ));
    }

    let combos = scan::combinations(config);
    for (prefix, extension) in &combos {
        spawn_combo(&engine, &base_string, prefix, extension, split, 0);
    }
    coordinate(&engine);
}

/// Spawns the threads that scan one folder/extension combination.
fn spawn_combo(
    engine: &Arc<Engine>,
    dir_url: &str,
    prefix: &str,
    extension: &str,
    split: usize,
    parent_depth: usize,
) {
    let items: Vec<ScanItem> = engine
        .wordlist
        .iter()
        .map(|word| {
            let path = scan::transform(word, prefix, extension, engine.config.ext_sub);
            let joined = engine.base.join(&path).to_string();
            ScanItem {
                url: joined,
                depth: parent_depth + scan::segments_added(dir_url, &joined),
                is_directory_hint: false,
                is_scraped: false,
                code: 1,
            }
        })
        .collect();
    let chunks = scan::deal(&items, split);
    for chunk in chunks {
        engine.active.fetch_add(1, Ordering::SeqCst);
        let engine = Arc::clone(engine);
        let dir = dir_url.to_string();
        std::thread::spawn(move || run_worker(engine, chunk, dir));
    }
}

/// The body of a single request thread.
fn run_worker(engine: Arc<Engine>, items: Vec<ScanItem>, dir_url: String) {
    engine.slots.acquire();
    log::debug!("Scanning {}", dir_url);
    let mut easy = crate::request::Easy::new();
    let mut consecutive = 0usize;
    for item in items {
        if let Some(ms) = engine.config.throttle {
            std::thread::sleep(Duration::from_millis(ms));
        }
        let mut worker = match crate::request_thread::Worker::new(
            Arc::clone(&engine.config),
            engine.defaults.clone(),
            Arc::clone(&engine),
        ) {
            Some(worker) => worker,
            None => break,
        };
        if let Some(easy) = easy.as_mut() {
            worker.set_easy(easy);
        }
        if worker.process(&item) {
            consecutive = 0;
        } else {
            consecutive += 1;
            if engine.config.max_errors > 0 && consecutive >= engine.config.max_errors {
                engine.warn(format!(
                    "Thread scanning {} stopping due to multiple consecutive errors received",
                    item.url
                ));
                break;
            }
        }
    }
    log::debug!("Finished scanning {}", dir_url);
    engine.slots.release();
    engine.active.fetch_sub(1, Ordering::SeqCst);
    engine.condition.notify_one();
}

/// Waits for all work of the current uri to finish, recursing as needed.
fn coordinate(engine: &Arc<Engine>) {
    loop {
        let active = engine.active.load(std::sync::atomic::Ordering::SeqCst);
        let next = {
            let mut guard = engine.pending.lock().unwrap();
            if let Some(dir) = guard.pop_front() {
                Some(dir)
            } else if active == 0 {
                None
            } else {
                guard = engine.condition.wait(guard).unwrap();
                guard.pop_front()
            }
        };
        match next {
            Some(dir) => recurse(engine, dir),
            None => break,
        }
    }
}

/// Validates and scans a directory that was discovered while scanning.
fn recurse(engine: &Arc<Engine>, dir: PendingDir) {
    let signature = engine.validator.detect(&dir.url);
    engine.signature = signature;
    if !engine.config.silent {
        engine.info(format!(
            "Detected nonexistent paths for {} are ({})",
            dir.url,
            signature.describe()
        ));
    }
    let split = engine.config.wordlist_split.max(1);
    let combos = scan::combinations(&engine.config);
    for (prefix, extension) in &combos {
        spawn_combo(engine, &dir.url, prefix, extension, split, dir.depth);
    }
}
