//! The worker that turns scan items into requests and reports.
//!
//! Every worker owns one slice of the wordlist for a single folder/extension
//! combination.  It acquires a thread slot for its whole lifetime, walks its
//! items in order and reports everything it finds to the output thread.
//! Directories discovered on the way are handed over to the coordinator.

use crate::arg_parse::Config;
use crate::report::FoundPath;
use crate::request::{CurlFailure, Defaults, Easy, Response};
use crate::scan::{segment_count, ScanItem};
use crate::validator::NotFound;
use log::trace;
use std::sync::Arc;

/// Whether the response should be shown to the user.
fn showable(config: &Config, url: &str, code: u16) -> bool {
    if !config.code_whitelist.is_empty() {
        return config.code_whitelist.contains(&code);
    }
    if config.code_blacklist.contains(&code) {
        return false;
    }
    if code == 403 && !config.show_htaccess && url.contains(".ht") {
        return false;
    }
    true
}

/// Decides whether a discovered directory should be scanned recursively.
fn may_recurse(config: &Config, is_listable: bool, code: u16) -> bool {
    if config.disable_recursion {
        return false;
    }
    if code == 401 && !config.scan_401 {
        return false;
    }
    if code == 403 && !config.scan_403 {
        return false;
    }
    if is_listable && !config.scan_listable {
        return false;
    }
    true
}

/// A worker processes the items of one scan.
pub struct Worker {
    easy: Easy,
    config: Arc<Config>,
    defaults: Defaults,
    signature: NotFound,
    last: Option<Response>,
}

impl Worker {
    pub fn new(
        config: Arc<Config>,
        defaults: Defaults,
        signature: NotFound,
    ) -> Option<Worker> {
        let easy = Easy::new()?;
        Some(Worker {
            easy,
            config,
            defaults,
            signature,
            last: None,
        })
    }

    /// Handles one item.  Returns false when the request failed.
    pub fn process(&mut self, engine: &Arc<crate::scan::Engine>, item: &ScanItem) -> bool {
        if item.code == 0 {
            self.code_zero(&item.url);
            return true;
        }
        let limit = engine.recursion_limit();
        if item.depth + 2 > limit {
            if item.is_scraped {
                self.report_scraped(engine, &item.url);
            }
            engine.queue_recursion(&item.url, item.depth);
            return true;
        }
        let mut url = item.url.clone();
        let mut response = self.easy.perform(&url, &self.defaults);
        if let Some(failure) = &response.failure {
            self.fail(engine, &url, failure);
            return false;
        }
        let mut redirect_url = String::new();
        if response.code == 301 || response.code == 302 {
            let target = self.follow(&url, &response.location);
            if target == format!("{}/", url) {
                url = target;
                response = self.easy.perform(&url, &self.defaults);
                if let Some(failure) = &response.failure {
                    self.fail(engine, &url, failure);
                    return false;
                }
            } else {
                redirect_url = target;
            }
        }
        let size = response.size();
        if self.signature.matches(response.code, size) {
            self.not_found(&url);
            return true;
        }
        if !showable(&self.config, &url, response.code) {
            return true;
        }
        let body = String::from_utf8_lossy(&response.body).to_string();
        let is_directory = url.ends_with('/');
        let is_listable = is_directory && body.contains("directory listing for");
        if is_listable && self.config.scrape_listable {
            self.scrape(engine, &url, &body, item.depth);
        }
        self.report(
            engine,
            &url,
            response.code,
            size,
            is_directory,
            is_listable,
            redirect_url,
        );
        if is_directory && may_recurse(&self.config, is_listable, response.code) {
            engine.queue_recursion(&url, item.depth);
        }
        true
    }

    /// Resolves the `Location` header of a redirect response.
    fn follow(&self, url: &str, location: &Option<String>) -> String {
        let base = &self.engine_base;
        let raw = location.as_ref().map(|s| s.as_str()).unwrap_or_else(|| {
            panic!("called `Option::unwrap()` on a `None` value");
        });
        match base.join(raw) {
            Ok(resolved) => resolved.to_string(),
            Err(_) => url.to_string(),
        }
    }

    fn engine_base(&self) {}
}
