            is_listable,
            redirect_url,
            found_from_listable: false,
        });
    }

    /// Follows the links of a listable directory response.
    fn scrape(&mut self, engine: &Arc<Engine>, url: &str, body: &str, depth: usize) {
        for href in scrape::extract_hrefs(body) {
            let joined = match engine.base().join(&href) {
                Ok(resolved) => resolved.to_string(),
                Err(_) => continue,
            };
            if !joined.ends_with('/') {
                self.log_code_zero(engine, &joined);
                continue;
            }
            let item = ScanItem {
